import { test, expect } from '@playwright/test';

test.describe('File Download on Export Button Click', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/export-page');
  });

  test('should trigger file download when export button is clicked', async ({ page }) => {
    // Verify export button is visible and enabled
    const exportButton = page.getByRole('button', { name: /export/i });
    await expect(exportButton).toBeVisible();
    await expect(exportButton).toBeEnabled();

    // Verify download dialog is not visible initially
    const downloadDialog = page.getByRole('dialog', { name: /download file/i });
    await expect(downloadDialog).not.toBeVisible();

    // Click export button to trigger download
    await exportButton.click();

    // Wait for download dialog to appear
    await page.waitForTimeout(500);

    // Verify download dialog is visible
    await expect(downloadDialog).toBeVisible();

    // Verify download dialog contains file name
    const fileName = page.getByText(/exported-data.csv/i);
    await expect(fileName).toBeVisible();

    // Verify download button is present
    const downloadButton = page.getByRole('button', { name: /download/i });
    await expect(downloadButton).toBeVisible();

    // Verify download button is enabled
    await expect(downloadButton).toBeEnabled();

    // Verify file download starts
    await expect(downloadButton).toHaveAttribute('aria-label', 'Download file');
  });

  test('should handle failed file download and display error message', async ({ page }) => {
    // Mock API response to simulate failed download
    await page.route('**/api/export', (route) => {
      route.abort('Failed to download file');
    });

    // Verify export button is visible and enabled
    const exportButton = page.getByRole('button', { name: /export/i });
    await expect(exportButton).toBeVisible();
    await expect(exportButton).toBeEnabled();

    // Click export button to trigger download
    await exportButton.click();

    // Wait for download dialog to appear
    await page.waitForTimeout(500);

    // Verify download dialog is visible
    const downloadDialog = page.getByRole('dialog', { name: /download file/i });
    await expect(downloadDialog).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/failed to download file/i);
    await expect(errorMessage).toBeVisible();

    // Verify download button is disabled
    const downloadButton = page.getByRole('button', { name: /download/i });
    await expect(downloadButton).toBeDisabled();

    // Verify download dialog has cancel button
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(cancelButton).toBeVisible();

    // Verify download dialog has retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
  });
});
